// GENERATED at build time from the geoBoundaries gbOpen dataset
// (https://www.geoboundaries.org/api/current/gbOpen/ALL/ADM1/ — each
// country's simplifiedGeometryGeoJSON, GitHub raw under
// https://github.com/wmgeolab/geoBoundaries/raw/9469f09/releaseData/
// gbOpen/<ISO>/ADM1/). The SAME source geometry as admin1.ts, but
// grouped by region: every ADM1 unit keeps its dataset name and its
// own rings, which the selection highlight needs (fill + outline of
// the tapped place's region). Same simplification as admin1.ts
// (Douglas-Peucker eps 0.05 deg, coords at 3 decimals, micro-rings
// dropped by span), delta-encoded (degrees x1000) like admin1.ts.
// China is excluded — its finer DataV province/prefecture geometry
// (china-admin.ts) covers it. Downloaded 2026-11-10. See DATA-PLAN.md.
// Payload format (perf repack, 2026-11-18): the integer stream is
// zigzag-varint encoded and base64-packed into string literals instead
// of comma-separated number arrays — identical values after decode,
// but the bundle shrinks by ~half and the JS parser sees a few string
// literals instead of millions of number tokens (the arrays dominated
// cold-start parse time on phones).

export interface Adm1Unit {
  name: string;
  rings: number[][];
}

interface Adm1CountryEnc {
  names: string[];
  offs: number[];
  packed: string;
}

function unpackInts(packed: string): number[] {
  const bin = atob(packed);
  const out: number[] = [];
  let i = 0;
  while (i < bin.length) {
    let u = 0;
    let shift = 0;
    for (;;) {
      const b = bin.charCodeAt(i++);
      u += (b & 0x7f) * 2 ** shift;
      if (!(b & 0x80)) break;
      shift += 7;
    }
    out.push(u % 2 === 0 ? u / 2 : -(u + 1) / 2);
  }
  return out;
}

