const cache = new Map<string, Adm1Unit[]>();
const intsCache = new Map<string, number[]>();

// Decoded ADM1 units (dataset name + boundary rings) for one
// country, or null when the dataset has no grouped geometry for
// it (China included — callers use the DataV set there).
export function getAdm1Units(iso: string): Adm1Unit[] | null {
  const hit = cache.get(iso);
  if (hit) return hit;
  const rec = ENC_BY_ISO[iso];
  if (!rec) return null;
  let enc = intsCache.get(iso);
  if (!enc) {
    enc = unpackInts(rec.packed);
    intsCache.set(iso, enc);
  }
  const units: Adm1Unit[] = rec.names.map((name, ui) => {
    let i = rec.offs[ui] ?? 0;
    const ringCount = enc[i++] ?? 0;
    const rings: number[][] = [];
    for (let r = 0; r < ringCount; r++) {
      const n = enc[i++] ?? 0;
      const ring: number[] = [];
      let l = 0;
      let a = 0;
      for (let k = 0; k < n; k++) {
        l += enc[i++] ?? 0;
        a += enc[i++] ?? 0;
        ring.push(l / 1000, a / 1000);
      }
      rings.push(ring);
    }
    return { name, rings };
  });
  cache.set(iso, units);
  return units;
}
